CREATE TABLE IF NOT EXISTS product_media (id CHAR(36) PRIMARY KEY,product_id CHAR(36) NOT NULL,url TEXT NOT NULL,public_id VARCHAR(255) NOT NULL,resource_type ENUM('image','video') NOT NULL,format VARCHAR(20) NOT NULL,file_size BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT media_product_fk FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,INDEX media_product_idx(product_id));
